DELETE rp
FROM role_permissions rp
JOIN roles r ON r.role_id = rp.role_id
JOIN permissions p ON p.permission_id = rp.permission_id
WHERE r.role_code = #{roleCode}
  AND p.permission_code = #{permissionCode}

mapper.update:
UPDATE departments
SET leader_employee_id = #{employeeId}
WHERE department_id = #{departmentId}

mapper.select:
SELECT COUNT(*)
FROM employees e
WHERE e.company_id = #{companyId}
  AND e.deleted_at IS NULL

  AND (e.employee_name LIKE CONCAT('%', #{keyword}, '%')
       OR e.employee_number LIKE CONCAT('%', #{keyword}, '%')
       OR e.email LIKE CONCAT('%', #{keyword}, '%'))


  AND e.department_id = #{departmentId}


  AND e.position_id = #{positionId}

SELECT e.employee_id AS employeeId, e.employee_number AS employeeNumber, e.employee_name AS employeeName, e.email, e.phone, e.department_id AS departmentId, d.department_name AS departmentName, e.position_id AS positionId, p.position_name AS positionName, e.hire_date AS hireDate, e.termination_date AS terminationDate, e.employment_status AS employmentStatus, e.employment_type AS employmentType, e.profile_file_id AS profileFileId, a.login_id AS loginId, GROUP_CONCAT(DISTINCT r.role_name ORDER BY r.role_id SEPARATOR ', ') AS roleNames FROM employees e LEFT JOIN departments d ON d.department_id = e.department_id LEFT JOIN positions p ON p.position_id = e.position_id LEFT JOIN accounts a ON a.employee_id = e.employee_id AND a.deleted_at IS NULL LEFT JOIN account_roles ar ON ar.account_id = a.account_id LEFT JOIN roles r ON r.role_id = ar.role_id WHERE e.company_id = #{companyId} AND e.deleted_at IS NULL
AND (e.employee_name LIKE CONCAT('%', #{keyword}, '%') OR e.employee_number LIKE CONCAT('%', #{keyword}, '%') OR e.email LIKE CONCAT('%', #{keyword}, '%'))
AND e.department_id = #{departmentId}
AND e.position_id = #{positionId}
GROUP BY e.employee_id, e.employee_number, e.employee_name, e.email, e.phone, e.department_id, d.department_name, e.position_id, p.position_name, e.hire_date, e.termination_date, e.employment_status, e.employment_type, e.profile_file_id, a.login_id ORDER BY e.employee_number LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE employees
SET deleted_at = NOW(6), version = version + 1
WHERE company_id = #{companyId}
  AND employee_id = #{employeeId}
  AND deleted_at IS NULL

UPDATE departments
SET parent_department_id = #{parentDepartmentId},
    leader_employee_id = #{leaderEmployeeId},
    department_code = #{departmentCode},
    department_name = #{departmentName},
    description = #{description},
    sort_order = #{sortOrder}
WHERE company_id = #{companyId}
  AND department_id = #{departmentId}
  AND deleted_at IS NULL

UPDATE positions
SET position_code = #{positionCode},
    position_name = #{positionName},
    position_level = #{positionLevel},
    sort_order = #{sortOrder}
WHERE company_id = #{companyId}
  AND position_id = #{positionId}
  AND deleted_at IS NULL

mapper.select:
SELECT COUNT(*)
FROM leave_requests lr
JOIN employees e ON e.employee_id = lr.employee_id
WHERE e.company_id = #{companyId}
  AND (
    #{admin} = TRUE
    OR (#{manager} = TRUE AND e.department_id = #{departmentId})
    OR lr.employee_id = #{employeeId}
  )

  AND lr.status = #{status}

SELECT lr.leave_request_id AS leaveRequestId, lr.employee_id AS employeeId, e.employee_name AS employeeName, e.employee_number AS employeeNumber, d.department_name AS departmentName, lt.leave_type_name AS leaveTypeName, lr.leave_unit AS leaveUnit, lr.start_date AS startDate, lr.end_date AS endDate, lr.requested_days AS requestedDays, lr.reason, lr.status, lr.rejection_reason AS rejectionReason, lr.approval_document_id AS approvalDocumentId, lr.submitted_at AS submittedAt FROM leave_requests lr JOIN employees e ON e.employee_id = lr.employee_id LEFT JOIN departments d ON d.department_id = e.department_id JOIN leave_types lt ON lt.leave_type_id = lr.leave_type_id WHERE e.company_id = #{companyId} AND ( #{admin} = TRUE OR (#{manager} = TRUE AND e.department_id = #{departmentId}) OR lr.employee_id = #{employeeId} )
AND lr.status = #{status}
ORDER BY lr.created_at DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE approval_documents
SET business_id = #{businessId}
WHERE approval_document_id = #{documentId}

UPDATE leave_balances
SET pending_days = pending_days + #{days}, version = version + 1
WHERE leave_balance_id = #{leaveBalanceId}

mapper.select:
SELECT n.notice_id AS noticeId, n.title, n.pinned, n.published, n.view_count AS viewCount, n.published_at AS publishedAt, n.created_at AS createdAt, nc.category_name AS categoryName, e.employee_name AS authorName, COUNT(na.file_id) AS attachmentCount FROM notices n LEFT JOIN notice_categories nc ON nc.notice_category_id = n.notice_category_id JOIN accounts a ON a.account_id = n.author_account_id JOIN employees e ON e.employee_id = a.employee_id LEFT JOIN notice_attachments na ON na.notice_id = n.notice_id WHERE n.company_id = #{companyId} AND n.published = TRUE AND n.deleted_at IS NULL
AND (n.title LIKE CONCAT('%', #{keyword}, '%') OR n.content LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY n.notice_id, n.title, n.pinned, n.published, n.view_count, n.published_at, n.created_at, nc.category_name, e.employee_name ORDER BY n.pinned DESC, n.published_at DESC, n.created_at DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE notices
SET deleted_at = NOW(6), deleted_by_account_id = #{accountId}, version = version + 1
WHERE company_id = #{companyId}
  AND notice_id = #{noticeId}
  AND deleted_at IS NULL

mapper.select:
SELECT r.resource_id AS resourceId, r.title, r.description, r.download_count AS downloadCount, r.created_at AS createdAt, e.employee_name AS authorName, fa.file_id AS fileId, fa.original_name AS originalName, fa.content_type AS contentType, fa.size_bytes AS sizeBytes, fa.extension FROM resources r JOIN accounts a ON a.account_id = r.author_account_id JOIN employees e ON e.employee_id = a.employee_id LEFT JOIN resource_files rf ON rf.resource_id = r.resource_id LEFT JOIN file_assets fa ON fa.file_id = rf.file_id AND fa.deleted_at IS NULL WHERE r.company_id = #{companyId} AND r.published = TRUE AND r.deleted_at IS NULL
AND (r.title LIKE CONCAT('%', #{keyword}, '%') OR r.description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY r.created_at DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE calendar_events
SET deleted_at = NOW(6), version = version + 1
WHERE company_id = #{companyId}
  AND calendar_event_id = #{eventId}
  AND deleted_at IS NULL
  AND (#{admin} = TRUE OR organizer_employee_id = #{employeeId})

UPDATE internal_messages
SET read_at = COALESCE(read_at, NOW(6))
WHERE message_id = #{messageId}
  AND recipient_account_id = #{accountId}

UPDATE notifications
SET read_at = COALESCE(read_at, NOW(6))
WHERE notification_id = #{notificationId}
  AND recipient_account_id = #{accountId}
